	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	private Long id;

	@Embedded
	private Money amount;

	protected MoneyEmbeddingHost() {
		// required by JPA
	}

	public MoneyEmbeddingHost(Money amount) {
		this.amount = amount;
	}

	public Money getAmount() {
		return amount;
	}
}

