package hu.bankmonitor.payments.common;

import hu.bankmonitor.testsupport.moneymapping.MoneyEmbeddingHost;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;
import org.springframework.boot.jpa.test.autoconfigure.TestEntityManager;
import org.springframework.boot.persistence.autoconfigure.EntityScan;
import org.springframework.test.context.TestPropertySource;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * One {@link Money} flattens to two columns, and the currency is a {@code varchar} holding
 * the currency's name.
 *
 * <p>Neither half is the default. Left unannotated, JPA stores an enum by its
 * <b>ordinal</b> — Hibernate 7 emits a {@code tinyint} — and reordering the constants
 * would silently reinterpret every row already written. {@code @Enumerated(STRING)} alone
 * then emits a <b>native H2 {@code enum}</b> column rather than a varchar, proved by
 * {@code RecordAsEmbeddableSpikeTest}, which is H2-specific in a schema the README's TODO
 * list says has to move to Postgres. Design decision 29 chose to pin {@code varchar}, and
 * that pin is one annotation that nothing else would notice the loss of.
 *
 * <p>So this test is arranged the way the application really runs rather than the way a
 * JPA test usually is: the table comes from a migration and Hibernate is on
 * {@code validate}, exactly as ticket 08's accounts table will be. The mapping is
 * therefore checked <em>against hand-written SQL</em> — remove the pin and the context
 * fails to start, naming the column, which is the failure ticket 08 would otherwise meet
 * while also writing that SQL.
 *
 * <p>The arrangement is not only more faithful, it is the one that works.
 * {@code ddl-auto=create-drop} emits a check constraint for the enum
 * ({@code check (currency in ('EUR','USD','HUF'))}) that is unusable on the throwaway
 * database {@code @DataJpaTest} substitutes: every insert fails with H2's
 * {@code Check constraint invalid}, caused by {@code The database has been closed}. Since
 * Hibernate emits no DDL anywhere in this application, that is a dead end rather than a
 * problem to solve.
 */
@DataJpaTest
@EntityScan(basePackageClasses = MoneyEmbeddingHost.class)
@TestPropertySource(properties = {
		// The host entity is test-only, so its table ships beside this test rather than
		// in db/migration, which Flyway owns for the schema the application runs on.
		"spring.flyway.locations=classpath:db/testmigration/moneymapping",
		// The application's own setting, restated because the claim below rests on it.
		"spring.jpa.hibernate.ddl-auto=validate"
})
class MoneyMapsToTwoColumnsTest {

	@Autowired
	private TestEntityManager entityManager;

	/**
	 * Startup is the assertion: {@code validate} has already compared the mapping against
	 * the migration by the time this method runs. The body confirms the agreement is a
	 * working one rather than merely a nominal one.
	 */
	@Test
	@DisplayName("the mapping agrees with a hand-written varchar column, and money round trips through it")
	void roundTripsThroughAHandWrittenSchema() {
		Money amount = new Money(123_45L, Currency.EUR);

		Long id = entityManager.persistAndGetId(new MoneyEmbeddingHost(amount), Long.class);
		entityManager.flush();
		entityManager.clear();

		assertThat(entityManager.find(MoneyEmbeddingHost.class, id).getAmount()).isEqualTo(amount);
	}

	/**
	 * Read in SQL rather than through Hibernate, so this asserts what is in the database
	 * rather than what the mapping is willing to say about it. {@code 'HUF'} is the fact
	 * that matters: an ordinal would be stored here as {@code 2}.
	 *
	 * <p>Note what the implicit naming strategy does <em>not</em> do — the host's field is
	 * called {@code amount} and no column is named after it. An entity carrying two Money
	 * figures therefore needs {@code @AttributeOverride} to keep them apart, which is
	 * ticket 08's first job.
	 */
	@Test
	@DisplayName("the count and the currency are stored as minor_units and a currency name")
	void storesTheCountAndTheCurrencyName() {
		entityManager.persistAndFlush(new MoneyEmbeddingHost(new Money(-150L, Currency.HUF)));
		entityManager.clear();

		@SuppressWarnings("unchecked")
		List<Object[]> rows = entityManager.getEntityManager()
				.createNativeQuery("SELECT minor_units, currency FROM money_embedding_host")
				.getResultList();

		assertThat(rows).hasSize(1);
		assertThat(((Number) rows.getFirst()[0]).longValue()).isEqualTo(-150L);
		assertThat(rows.getFirst()[1]).hasToString("HUF");
	}
}

