package hu.bankmonitor.payments.common;

import hu.bankmonitor.testsupport.MoneyEmbeddingHost;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;
import org.springframework.boot.jpa.test.autoconfigure.TestEntityManager;
import org.springframework.boot.persistence.autoconfigure.EntityScan;
import org.springframework.test.context.TestPropertySource;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * One {@link Money} flattens to two columns, and the currency is a {@code varchar}.
 *
 * <p>The second half is the one worth a test. {@code @Enumerated(EnumType.STRING)} alone
 * emits a <em>native</em> H2 {@code enum} column on Hibernate 7 — proved by
 * {@code RecordAsEmbeddableSpikeTest} — and design decision 29 chose to pin
 * {@code varchar} instead, so that the schema has a chance of surviving the move to
 * Postgres the README's TODO list calls for. That pin is a single annotation, and without
 * this test nothing would notice its removal until a migration failed {@code validate} at
 * startup.
 *
 * <p>It also fixes the column <em>names</em> ahead of ticket 08, which ships the first
 * migration that has to match them. Note what the implicit naming strategy does not do:
 * the host's field is called {@code amount} and no column is called {@code amount_}
 * anything. An entity embedding two Money figures therefore needs
 * {@code @AttributeOverride} to keep them apart.
 */
@DataJpaTest
@EntityScan(basePackageClasses = MoneyEmbeddingHost.class)
@TestPropertySource(properties = {
		// This entity is test-only and no migration will ever create its table, so it
		// owns its schema rather than borrowing the one Flyway manages.
		"spring.jpa.hibernate.ddl-auto=create-drop",
		"spring.flyway.enabled=false",
		"logging.level.org.hibernate.SQL=DEBUG",
		"logging.level.org.hibernate.orm.jdbc.bind=TRACE"
})
class MoneyMapsToTwoColumnsTest {

	@Autowired
	private TestEntityManager entityManager;

	@Test
	@DisplayName("money survives a round trip through the database")
	void roundTripsThroughTheDatabase() {
		Money amount = new Money(123_45L, Currency.EUR);

		Long id = entityManager.persistAndGetId(new MoneyEmbeddingHost(amount), Long.class);
		entityManager.flush();
		entityManager.clear();

		assertThat(entityManager.find(MoneyEmbeddingHost.class, id).getAmount()).isEqualTo(amount);
	}

	/**
	 * Read in SQL rather than through Hibernate, so this asserts what is in the database
	 * rather than what the mapping is willing to say about it.
	 */
	@Test
	@DisplayName("the count and the currency are columns named minor_units and currency")
	void flattensIntoTwoNamedColumns() {
		entityManager.persistAndFlush(new MoneyEmbeddingHost(new Money(-150L, Currency.HUF)));
		entityManager.clear();

		List<Object[]> rows = query("SELECT minor_units, currency FROM money_embedding_host");

		assertThat(rows).hasSize(1);
		assertThat(((Number) rows.getFirst()[0]).longValue()).isEqualTo(-150L);
		assertThat(rows.getFirst()[1]).hasToString("HUF");
	}

	@Test
	@DisplayName("the currency is a varchar, not the native enum Hibernate would emit unpinned")
	void storesTheCurrencyAsAVarchar() {
		List<Object[]> columnTypes = query("""
				SELECT data_type FROM information_schema.columns
				WHERE table_name = 'MONEY_EMBEDDING_HOST' AND column_name = 'CURRENCY'
				""");

		assertThat(columnTypes).singleElement().hasToString("CHARACTER VARYING");
	}

	@SuppressWarnings("unchecked")
	private List<Object[]> query(String sql) {
		return entityManager.getEntityManager().createNativeQuery(sql).getResultList();
	}
}
